import ast,importlib.metadata as m,json,platform
d=m.distribution("torch");p=d.locate_file("torch/version.py")
values={}
for item in ast.parse(p.read_text()).body:
 if isinstance(item,ast.AnnAssign) and isinstance(item.target,ast.Name):
  try: values[item.target.id]=ast.literal_eval(item.value)
  except (ValueError,TypeError): pass
print(json.dumps({"python":platform.python_version(),"torch_distribution":d.version,"torch_cuda_build":values.get("cuda"),"read_metadata_only":True,"torch_imported":False}))
